export type RequestInput = { tenant_id: number; resource_id: number; generation: number };
export const cacheToken = (tenant: number, resource: number, generation: number) => tenant * 1_000_000 + resource * 1_000 + generation;
export const handle = (value: RequestInput) => ({ token: cacheToken(value.tenant_id, value.resource_id, value.generation), state: "isolated" });
export async function loadParley() { return { cache_token: (tenant: number, resource: number, generation: number) => cacheToken(tenant, resource, generation) }; }

