from pydantic import BaseModel, ConfigDict

class RequestInput(BaseModel):
    model_config = ConfigDict(extra="forbid", strict=True)
    slots: int
    reserved: int
    requested: int
    priority: bool

def usable_slots(slots: int, reserved: int) -> int:
    return max(slots - reserved, 0)


def demand_jobs(requested: int, priority: bool) -> int:
    return requested + (2 if priority else 0)


def accepted_jobs(slots: int, reserved: int, requested: int, priority: bool) -> int:
    return min(usable_slots(slots, reserved), demand_jobs(requested, priority))


def overflow_jobs(slots: int, reserved: int, requested: int, priority: bool) -> int:
    return max(demand_jobs(requested, priority) - usable_slots(slots, reserved), 0)

def handle(value: RequestInput) -> dict[str, object]:
    usable = usable_slots(value.slots, value.reserved)
    demand = demand_jobs(value.requested, value.priority)
    accepted = accepted_jobs(value.slots, value.reserved, value.requested, value.priority)
    overflow = overflow_jobs(value.slots, value.reserved, value.requested, value.priority)
    return {"usable": usable, "demand": demand, "accepted": accepted, "overflow": overflow, "state": "overloaded" if overflow > 0 else "clear"}

